.sea { position: absolute; z-index: 5; top: var(--sea-top); right: 0; bottom: 0; left: 0; overflow: visible; background: transparent; transition: top 1.35s var(--wave-state-ease); }
.wave { position: absolute; left: -12%; width: 124%; height: calc(48% * var(--wave-height)); border-radius: 46% 54% 0 0 / 22% 25% 0 0; background: var(--foam); transform-origin: 50% 100%; transition: background 1.8s var(--ease-scene); animation: wave-swell var(--wave-speed) ease-in-out infinite alternate var(--specimen-play-state); }
.wave i { position: absolute; inset: 9px 0 0; border-radius: inherit; background: repeating-radial-gradient(ellipse at 50% 0,transparent 0 38px,rgba(255,255,255,.16) 40px 41px,transparent 43px 82px),linear-gradient(var(--wave-color),var(--wave-color)); transition: background 1.8s var(--ease-scene); }
.wave-far { --wave-color: var(--far-sea); z-index: 1; top: -7%; animation-duration: calc(var(--wave-speed) * .82); }
.wave-mid { --wave-color: var(--mid-sea); z-index: 2; top: 28%; left: -18%; width: 136%; animation-delay: calc(var(--wave-speed) * -.4); animation-direction: alternate-reverse; }
.wave-near { --wave-color: var(--near-sea); z-index: 3; top: 58%; height: 56%; animation-duration: calc(var(--wave-speed) * 1.18); }
:root[data-foam="false"] .wave { background: transparent; }
@keyframes wave-swell { 0%{transform:translateX(-2%) rotate(-1deg) scaleY(.94)} 50%{border-radius:54% 46% 0 0 / 29% 18% 0 0} 100%{transform:translateX(3%) rotate(1deg) scaleY(1.08)} }
